{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "BI 425809 absolute oral bioavailability was 71.64% (90% CI 64.28–79.84) in fasted humans after a 25 mg tablet, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C43"],
      "claim": "Propylthiouracil mean absolute oral bioavailability was 77 ± 13% in humans after 400 mg oral vs IV, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C17"],
      "claim": "Pentazocine mean absolute oral bioavailability was 18% in healthy subjects after 100 mg tablets vs IV, below the 20% threshold."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C17"],
  "decision_summary": "Most transferred absolute bioavailability measurements are clearly above 20% (e.g., 71.6%, 77%, 82%), while one molecule is consistently below threshold at ~18%. The positive evidence is more consistent and direct, so high bioavailability is predicted with moderate confidence.",
  "evidence_gaps": [
    "Pentazocine individual oral bioavailability values range from 14.6% to 31.6%; the representative mean is 18%, but this variability adds uncertainty.",
    "Altered-condition records for pentazocine (e.g., cirrhosis) were not used for threshold classification."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C42", "C43"],
  "revision_action": "initial",
  "supportive_card_ids": ["C42", "C43"]
}

